import { readFile } from "node:fs/promises";

const MAX_SCHEMA_VERSION = 4;
const SCHEMA_ID = `cfg-schema-v${MAX_SCHEMA_VERSION}`;
const VERSION_KEY = "schema";

function checkVersion(declared, layer) {
  if (declared === undefined) return;
  const match = /^cfg-schema-v(\d+)$/.exec(String(declared));
  if (!match) {
    throw new Error(`${layer} config declares invalid schema "${declared}"`);
  }
  if (Number(match[1]) > MAX_SCHEMA_VERSION) {
    throw new Error(
      `${layer} config declares ${declared}, newer than supported ${SCHEMA_ID}`,
    );
  }
}

async function readLayer(path, layer) {
  if (!path) return null;
  let text;
  try {
    text = await readFile(path, "utf8");
  } catch (err) {
    if (err.code === "ENOENT") return null;
    throw err;
  }
  let data;
  try {
    data = JSON.parse(text);
  } catch (err) {
    throw new Error(`${layer} config ${path} is not valid JSON: ${err.message}`);
  }
  if (data === null || typeof data !== "object" || Array.isArray(data)) {
    throw new Error(`${layer} config ${path} must be a JSON object`);
  }
  return data;
}

function checkType(key, value, spec) {
  const actual = Array.isArray(value) ? "array" : typeof value;
  if (actual !== spec.type) {
    throw new Error(`Config key "${key}" must be ${spec.type}, got ${actual}`);
  }
  if (spec.enum && !spec.enum.includes(value)) {
    throw new Error(`Config key "${key}" must be one of: ${spec.enum.join(", ")}`);
  }
}

/**
 * Load config from three layers: defaults, project file, user file (later wins).
 * The merged result is checked against one schema.
 *
 * @param {object} options
 * @param {Record<string, unknown>} [options.defaults] built-in defaults
 * @param {Record<string, {type: string, enum?: unknown[]}>} options.schema
 *   top-level keys; type is a typeof name or "array"
 * @param {string} [options.projectPath]
 * @param {string} [options.userPath]
 * @returns {Promise<{values: object, sources: Record<string, string>, warnings: string[], schema: string}>}
 *   `sources` maps each key to the layer that set it, for the doctor command.
 */
export async function loadConfig({ defaults = {}, schema, projectPath, userPath } = {}) {
  if (!schema) throw new Error("loadConfig requires a schema");

  const layers = [
    ["defaults", defaults],
    ["project", await readLayer(projectPath, "project")],
    ["user", await readLayer(userPath, "user")],
  ];

  const values = {};
  const sources = {};
  const warnings = [];

  for (const [layer, data] of layers) {
    if (!data) continue;
    checkVersion(data[VERSION_KEY], layer);
    for (const [key, value] of Object.entries(data)) {
      if (key === VERSION_KEY) continue;
      if (!Object.hasOwn(schema, key)) {
        warnings.push(`Unknown config key "${key}" in ${layer} layer`);
        continue;
      }
      values[key] = value;
      sources[key] = layer;
    }
  }

  for (const [key, value] of Object.entries(values)) {
    checkType(key, value, schema[key]);
  }

  return { values, sources, warnings, schema: SCHEMA_ID };
}

