const SCHEMA_KEY = "schema";

// One schema for the merged result: key -> type check. Extend as options are added.
const SCHEMA = {
  logLevel: (v) => ["debug", "info", "warn", "error"].includes(v),
  telemetry: (v) => typeof v === "boolean",
  timeoutMs: (v) => Number.isInteger(v) && v >= 0,
};

const DEFAULTS = {
  logLevel: "info",
  telemetry: false,
  timeoutMs: 30000,
};

async function readLayer(path, layer) {
  let text;
  try {
    text = await readFile(path, "utf8");
  } catch (err) {
    if (err.code === "ENOENT") return null;
    throw err;
  }
  let data;
  try {
    data = JSON.parse(text);
  } catch (err) {
    throw new Error(`${layer} config ${path}: invalid JSON (${err.message})`);
  }
  if (data === null || typeof data !== "object" || Array.isArray(data)) {
    throw new Error(`${layer} config ${path}: top level must be an object`);
  }
  return data;
}

function checkSchemaVersion(data, layer, path) {
  if (!(SCHEMA_KEY in data)) return;
  const match = /^cfg-schema-v(\d+)$/.exec(String(data[SCHEMA_KEY]));
  if (!match) {
    throw new Error(`${layer} config ${path}: unrecognized schema "${data[SCHEMA_KEY]}"`);
  }
  if (Number(match[1]) > SCHEMA_VERSION) {
    throw new Error(
      `${layer} config ${path}: declares ${data[SCHEMA_KEY]}, newer than supported ${SCHEMA_ID}`,
    );
  }
}

/**
 * Load config from built-in defaults, then the project file, then the user file.
 * Later layers win. Unknown keys produce a warning (key + layer) and are dropped.
 * Returns { values, sources, warnings, schema } where sources[key] is the layer
 * that set each value ("defaults" | "project" | "user").
 */
export async function loadConfig({ projectPath, userPath } = {}) {
  const values = { ...DEFAULTS };
  const sources = Object.fromEntries(Object.keys(DEFAULTS).map((k) => [k, "defaults"]));
  const warnings = [];

  const layers = [
    ["project", projectPath],
    ["user", userPath],
  ];
  for (const [layer, path] of layers) {
    if (!path) continue;
    const data = await readLayer(path, layer);
    if (!data) continue;
    checkSchemaVersion(data, layer, path);
    for (const [key, value] of Object.entries(data)) {
      if (key === SCHEMA_KEY) continue;
      if (!(key in SCHEMA)) {
        warnings.push({ key, layer, message: `unknown key "${key}" in ${layer} config` });
        continue;
      }
      values[key] = value;
      sources[key] = layer;
    }
  }

  for (const [key, valid] of Object.entries(SCHEMA)) {
    if (!valid(values[key])) {
      throw new Error(
        `invalid value for "${key}" (set by ${sources[key]}): ${JSON.stringify(values[key])}`,
      );
    }
  }

  return { values, sources, warnings, schema: SCHEMA_ID };
}
