}

async function readLayer(layer, file) {
  if (!file) return null;
  let text;
  try {
    text = await readFile(file, "utf8");
  } catch (err) {
    if (err.code === "ENOENT") return null;
    throw err;
  }
  let data;
  try {
    data = JSON.parse(text);
  } catch (err) {
    throw new Error(`${file}: invalid JSON (${err.message})`);
  }
  if (!isPlainObject(data)) throw new Error(`${file}: top level must be an object`);
  if (VERSION_KEY in data) {
    const version = parseSchemaVersion(data[VERSION_KEY], file);
    if (version > SCHEMA_VERSION) {
      throw new Error(
        `${file}: declares ${data[VERSION_KEY]}, newer than supported ${SCHEMA_PREFIX}${SCHEMA_VERSION}`,
      );
    }
    delete data[VERSION_KEY];
  }
  return data;
}

// Merges `data` into `target`, recording the layer for each leaf in `sources`.
// Keys absent from `schema` warn and are dropped; type mismatches throw.
function mergeLayer({ target, sources, data, schema, layer, path, warnings }) {
  for (const [key, value] of Object.entries(data)) {
    const dotted = path ? `${path}.${key}` : key;
    if (!Object.hasOwn(schema, key)) {
      warnings.push({ key: dotted, layer, message: `unknown key "${dotted}" in ${layer} layer` });
      continue;
    }
    const expected = schema[key];
    if (isPlainObject(expected)) {
      if (!isPlainObject(value)) {
        throw new Error(`${layer} layer: "${dotted}" must be an object`);
      }
      mergeLayer({ target: target[key], sources, data: value, schema: expected, layer, path: dotted, warnings });
      continue;
    }
    if (expected !== null && value !== null && typeof value !== typeof expected) {
      throw new Error(`${layer} layer: "${dotted}" must be of type ${typeof expected}`);
    }
    target[key] = value;
    sources[dotted] = layer;
  }
}

function seedDefaults(defaults, sources, path = "") {
  const out = {};
  for (const [key, value] of Object.entries(defaults)) {
    const dotted = path ? `${path}.${key}` : key;
    if (isPlainObject(value)) {
      out[key] = seedDefaults(value, sources, dotted);
    } else {
      out[key] = Array.isArray(value) ? [...value] : value;
      sources[dotted] = "defaults";
    }
  }
  return out;
}

