 * validates the merged result against the schema derived from `defaults`.
 *
 * Returns { config, sources, warnings }:
 *  - sources maps each dotted key to the layer that set it
 *  - warnings lists unknown keys as { key, layer, message }; never an error
 * Throws if a file declares a schema newer than cfg-schema-v4.
 */
export async function loadConfig({ projectFile, userFile, defaults = DEFAULTS } = {}) {
  const sources = {};
  const warnings = [];
  const config = seedDefaults(defaults, sources);

  for (const [layer, file] of [["project", projectFile], ["user", userFile]]) {
    const data = await readLayer(layer, file);
    if (data) mergeLayer({ target: config, sources, data, schema: defaults, layer, path: "", warnings });
  }

